'use strict';
const $=id=>document.getElementById(id),send=d=>parent.postMessage(d,location.origin);
const positions={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};
let mode='size',target='small',state='idle',balance=0,connected=false,pending=false,lastId='',rollingSince=0,history=[],lastResult=null;
function faces(values){$('dice-row').innerHTML=values.map(v=>`<div class="die" data-value="${v}" role="img" aria-label="${v} 点">${positions[v].map(p=>`<span class="pip" style="grid-area:${Math.floor(p/3)+1}/${p%3+1}"></span>`).join('')}</div>`).join('');}
function options(){document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===mode));$('options').innerHTML=mode==='size'?`<div class="size-options"><button data-size="small" aria-pressed="${target==='small'}">小<small>4–10 点</small></button><button data-size="big" aria-pressed="${target==='big'}">大<small>11–17 点</small></button></div>`:mode==='sum'?`<label>目标总点数<select id="sum" aria-label="目标总点数">${Array.from({length:16},(_,i)=>`<option value="${i+3}" ${target===i+3?'selected':''}>${i+3} 点</option>`).join('')}</select></label>`:'';$('rule').textContent=mode==='size'?'三颗骰子点数之和落在所选范围即命中；三同号不计大小。':mode==='sum'?'三颗骰子的总和必须等于目标点数，包含三同号。不同点数奖励不同。':'任意三个相同点数即命中，例如 2 · 2 · 2，包含 1 至 6。';$('prize').textContent=dicePrize(mode,target).toLocaleString();$('net').textContent=(dicePrize(mode,target)-50).toLocaleString();controls();}
function controls(){const locked=state==='rolling'||pending;document.querySelectorAll('[data-mode],[data-size],select').forEach(b=>b.disabled=locked);$('roll').disabled=!connected||locked||balance<50;$('roll').textContent=locked?'掷骰中…':balance<50?'积分不足':'掷出骰子 · 50 积分';$('hint').textContent=balance<50&&!locked?'积分不足 50，可返回大厅玩扫雷赚取积分。':'每局消耗 50 积分，未命中则无奖励。';}
$('modes').onclick=e=>{const b=e.target.closest('[data-mode]');if(!b||state==='rolling'||pending)return;mode=b.dataset.mode;target=mode==='size'?'small':mode==='sum'?10:null;options();};$('options').onclick=e=>{const b=e.target.closest('[data-size]');if(!b||state==='rolling'||pending)return;target=b.dataset.size;options();};$('options').onchange=e=>{if(e.target.id==='sum'){target=Number(e.target.value);options();}};
$('roll').onclick=()=>{if(!connected||pending||state==='rolling'||balance<50)return;pending=true;controls();send({type:'dice-roll',mode,target});};$('back').onclick=()=>send({type:'game-return'});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||!e.data)return;const d=e.data;if(d.type==='dice-error'){pending=false;controls();$('hint').textContent=d.message;return}if(d.type!=='dice-state')return;connected=true;pending=false;balance=d.balance;$('balance').textContent=balance.toLocaleString();const changed=d.state!==state||d.roundId!==lastId;state=d.state;lastId=d.roundId;if(changed){$('dice-row').classList.toggle('rolling',state==='rolling');$('dice-row').classList.toggle('landed',state==='finished');if(state==='rolling'){mode=d.mode;target=d.target;options();rollingSince=performance.now()-d.elapsed;$('round-label').textContent='ROLLING / 掷骰中';$('result').classList.remove('won');$('result').innerHTML='<span class="result-kicker">THREE DICE IN MOTION</span><strong>等待点数落定…</strong><p>奖励自动结算，无需手动领取</p>';}else if(d.result){const r=d.result;lastResult=r;faces(r.values);$('dice-row').setAttribute('aria-label','三颗骰子：'+r.values.join('、')+'，总计 '+r.sum+' 点');$('round-label').textContent='ROUND '+d.roundId.split('-')[1]+' / 已结算';$('result').classList.toggle('won',r.won);$('result').innerHTML=`<span class="result-kicker">${r.values.join(' + ')} = ${r.sum} 点</span><strong>${r.won?'命中！到账 '+r.amount.toLocaleString()+' 积分':'未命中 · 本局无奖励'}</strong><p>${r.won?'本局净赚 '+(r.amount-r.cost)+' 积分':'本局消耗 50 积分，换个模式再挑战'}</p>`;history.unshift(r);history=history.slice(0,7);$('history').innerHTML=history.map(h=>`<b class="${h.won?'hit':''}" title="${h.values.join(' + ')}">${h.sum}</b>`).join('');}}controls();});
setInterval(()=>{if(state==='rolling'&&!matchMedia('(prefers-reduced-motion: reduce)').matches){faces([0,1,2].map(i=>1+(Math.floor((performance.now()-rollingSince)/100)+i*2)%6));}},100);
faces([1,3,5]);options();$('hint').textContent='正在连接游戏平台…';send({type:'dice-ready'});
